__global__ void scaled_dot_product_attention(const float* query, const float* key, const float* value, float* scores, float* weights, float* context, int n) {
  if (blockIdx.x != 0 || threadIdx.x != 0) {
    return;
  }
  float maxScore = -1000000.0f;
  for (int k = 0; k < n; k++) {
    float score = 0.0f;
    for (int d = 0; d < 4; d++) {
      score += query[d] * key[k * 4 + d];
    }
    scores[k] = score * 0.5f;
    if (scores[k] > maxScore) {
      maxScore = scores[k];
    }
  }
  float total = 0.0f;
  for (int k = 0; k < n; k++) {
    weights[k] = expf(scores[k] - maxScore);
    total += weights[k];
  }
  for (int k = 0; k < n; k++) {
    weights[k] = weights[k] / total;
  }
  for (int d = 0; d < 4; d++) {
    context[d] = 0.0f;
    for (int k = 0; k < n; k++) {
      context[d] += weights[k] * value[k * 4 + d];
    }
  }
}
